import"//resources/cr_elements/cr_button/cr_button.js";import"//resources/cr_elements/cr_dialog/cr_dialog.js";import"//resources/cr_elements/cr_input/cr_input.js";import"//resources/cr_elements/cr_shared_style.css.js";import"//resources/cr_elements/chromeos/cros_color_overrides.css.js";import{PolymerElement}from"//resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{getTemplate}from"./password_prompt_dialog.html.js";class SettingsPasswordPromptDialogElement extends PolymerElement{static get is(){return"settings-password-prompt-dialog"}static get template(){return getTemplate()}static get properties(){return{passwordPromptText:{type:String,notify:true,value:""},inputValue_:{type:String,value:"",observer:"onInputValueChange_"},passwordInvalid_:{type:Boolean,value:false},quickUnlockPrivate:{type:Object,value:chrome.quickUnlockPrivate},waitingForPasswordCheck_:{type:Boolean,value:false}}}get passwordInput(){return this.shadowRoot.querySelector("cr-input")}connectedCallback(){super.connectedCallback();this.$.dialog.showModal();window.setTimeout((()=>{this.passwordInput.focus()}),1)}onCancelClick_(){if(this.$.dialog.open){this.$.dialog.close()}}submitPassword_(){this.waitingForPasswordCheck_=true;const password=this.passwordInput.value;if(!password){this.passwordInvalid_=false;this.waitingForPasswordCheck_=false;return}this.quickUnlockPrivate.getAuthToken(password,(tokenInfo=>{this.waitingForPasswordCheck_=false;if(chrome.runtime.lastError){this.passwordInvalid_=true;this.passwordInput.select();return}this.dispatchEvent(new CustomEvent("token-obtained",{bubbles:true,composed:true,detail:tokenInfo}));this.passwordInvalid_=false;if(this.$.dialog.open){this.$.dialog.close()}}))}onInputValueChange_(){this.passwordInvalid_=false}isConfirmEnabled_(){return!this.waitingForPasswordCheck_&&!this.passwordInvalid_&&!!this.inputValue_}}customElements.define(SettingsPasswordPromptDialogElement.is,SettingsPasswordPromptDialogElement);